А теперь про то, как такие вещи делаются «по-взрослому». Обычно на таких проектах нужно параллельно работать с несколькими компонентами и учитывать физические процессы. На рисунке ниже — проект Wi-Fi-кнопки, при нажатии на которую отправляется сообщение в Telegram. Нужно сначала подключить фреймворк embassy с созданием async-задачи для него. У функции есть цикл, но благодаря async она умеет спать, разгружая процессор. В цикле ждем, когда кнопка будет нажата, точнее — ждем момента, когда кнопку отпустили. Затем ждем 20 миллисекунд, за которые проходят все физические процессы с замыканием и искрением контакта. Если кнопка нажата, отправляем сообщение в канал, сделанный ниже через CriticalSectionRawMutex
/// Task: listen to button clicks 
#[embassy_executor::task()]
pub async fn task_button_clicks(mut button: gpio::Input< 'static>) {
 loop {
 // Wait for press (high→low transition)
 button.wait_for_falling_edge().await;

 // Debounce.
 embassy_time:: Timer:: after_millis(20).await;
 if button.is_low() {
 // Send ONE event
 defmt::debug!("Button clicked");
 let _ = BUTTON_CLICKS.try_send(()): // Non-blocking

 // Wait for it to be released. Don't send any more events.
 button.wait_for_high() .await;
 }
 }
}

/// Channel: button clicks.
static BUTTON_CLICKS: Channel<CriticalSectionRawMutex, (), 1> = Channel::new();
Читаем в одном канале, что кнопка нажата и отправляем сообщения в другой канал, через который будет отправляться сообщение в Telegram.
// Task: main logic
// — Read button clicks
// — Send them as Telegram messages
#[embassy_executor::task()]
pub async fn task_main() {
 loop {
 button::BUTTON_CLICKS.receive().await;
 telegram::send_telegram_message (MESSAGE_CONTENT);
 }
}

/// Send a message
pub fn send_telegram_message(msg: &str) {
 // We only got a reference. To take ownership, we need a copy.
 let owned: String<32> = String::try_from(msg).unwrap() ;
 match MESSAGES_QUEUE.try_send(owned) {
 Ok (()) => (),
 Err (_) => defmt::error!("Queue full: cannot send message"),
 }
}

/// Messages queue
static MESSAGES_QUEUE: Channel<CriticalSectionRawMutex, String::<32>, 8> = Channel:: new();
Третий сервис уже работает с Telegram. Для начала нужно прочитать восемь случайных байт с датчика случайных чисел, который находится в метастабильном состоянии и от любого шума и тепла его колбасит от 0 до 1, поэтому с него можно считать случайные байты. Дальше мы инициализируем буфер для TLS, и это целые 16 Кб, и это очень много для микроконтроллера, у которого всего 400 Кб, часть которых уже занята. И в конце создаем буфер по 4 Кб для чтения и записи. Итого 40 Кб, только чтобы отправить один запрос, поэтому для связи с внешним миром обычно используют отдельные чипы.
// Send a message
async fn telegram_send_message (stack: embassy_net::Stack<'_>,
send_to: i64, message: &str) -> Result<(), TelegramSendMessageError> {
 // TLS needs a random value
 let rnd = Rng::new();
 let tls_seed = {
 let mut bytes = [0; 8];
 rnd.read(&mut bytes);
 u64::from_le_bytes(bytes)
 };

 // Init TLS.
 let (mut rx_buffer, mut tx_buffer) = ([0; 16640], [0; 16640]);
 let tls = TlsConfig::new(
 tls_seed,
 &mut rx_buffer,
 &mut tx buffer,
 reqwless::client::TlsVerify::None,
 );
 let tcp_state = TcClientState::<1, 4096, 4096>::new();
 let tcp = TcpClient::new(stack, &tcp_state);
 let dns = DnsSocket::new(stack);
 let mut client = HttpClient::new_with_tls(&tcp, &dns, tls);
Конструируем сообщение. Затем сериализуем JSON, для этого опять нужна 256 байт памяти. Отправляем запрос и читаем ответ и тоже нужно 4 Кб памяти.
// Data
 let mut url: String<128> = String::new();
 use core::fmt::Write;
 write!(url, "https://api.telegram.org/bot{}/sendMessage", BOT_TOKEN).unwrap();
 let msg = TelegramMessageInput {
 chat_id: send_to,
 text: message,
 };
 let mut body_buf = [0u8; 256];
 let _body_len = serde_json_core::to_slice(&msg, &mut body_buf)?;

 // Request
 let mut buf = [0; 4096];
 let mut req = client.request(reqwless::request::Method::POST, url.as_str())
 .await?
 .content_type(ContentType::ApplicationJson)
 .body(body_buf.as_slice());
 let resp = req.send (&mut buf).await?;
Наконец читаем ответ до конца, и благодаря await можно уснуть, чтобы другое устройство могло перехватить управление, пока мы спим. Дешифруем UTF, если требуется. И вместо парсинга JSON мы просто ищем в нем подстроку “ok”:true — чтобы сэкономить память. При обращении к Telegram, наверное, не лучшая идея, так как они могут добавить пробел или изменить формат, а при обращении к своим серверам это отличный вариант.
// Read response
 let response = resp.body().read_to_end().await?;
 let resp_text = core::str::from_utf8(&response)
 .map_err(|_| TelegramSendMessageError::ResponseError)?;

 // Check for success
 if !resp_text.contains(r#" "ok":true"#) {
 defmt::error!("Telegram failed: {3", resp_text);
 return Err(TelegramSendMessageError::ResponseError)
 }

 // Ok
 return Ok(())
}
На реальных больших проектах это пишут сложнее и на С++. Например, используя операционную систему FreeRTOS в мозгах машины Tesla. Создают очередь, чтобы писать туда события нажатых кнопок. Затем создается задача с бесконечным циклом внутри. И если кнопка нажата или отпущена, то в очередь отправляется сообщение. Далее уведомляют планировщик, что функция может вздремнуть и пока можно отдать управление другим. Эта операционная система FreeRTOS оперирует не процессами, а функциями, у которых есть стек, приоритет и она может спать.
void gpio_input_task_init(void) {
 button_events_queue = xQueueCreate(8, sizeof(button_event_t));
 xTaskCreate(gpio_input_task, "gpio_input", configMINIMAL_STACK_SIZE, NULL, tskIDLE_PRIORITY + 1, NULL);
}

static void gpio_input_task(void *argument) {
 (void) argument;

 for (;;) {
 for (int ii = 0; i < BUTTON_COUNT; i++) {
 button_t *button = &buttons[i];
 bool pressed = read_button(button);
 if (pressed != button->is_pressed) {
 button->is_pressed = pressed;

 button_event_t event = {.button = (button_id_t)i, .pressed = pressed};
 xQueueSend(button_events_queue, &event, 0);
 }
 }
 vTaskDelay(pdMS_TO_TICKS(BUTTON_POLL_PERIOD_MS));
 }
}

static QueueHandle_t button_events_queue;

static bool read_button(const button_t *button) {
 return HAL_GPIO_ReadPin(button->port, button->pin) == GPIO_PIN_RESET;
}
